/* the window's icon (title bar / taskbar; the macOS Dock keeps the bundle's .icns) - nothing on failure */
static void mercs_set_window_icon(SDL_Window *w)
{
    SDL_Surface *s;
    if (!w) return;
    s = SDL_CreateSurfaceFrom(MERCS_ICON_SIZE, MERCS_ICON_SIZE, SDL_PIXELFORMAT_RGBA32, (void *)mercs_icon_rgba, MERCS_ICON_SIZE * 4);
    if (!s) return;
    SDL_SetWindowIcon(w, s);
    SDL_DestroySurface(s);
}
